import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class ContractTest{static void check(HashMap<Integer,Double>a,HashMap<Integer,Double>b){HashMap<Integer,Double>oldA=new HashMap<>(a),oldB=new HashMap<>(b);HashMap<Integer,Double>actual=TaskBinding.add(a,b);assertNotNull(actual);assertEquals(oldA,a);assertEquals(oldB,b);Set<Integer>keys=new HashSet<>(a.keySet());keys.addAll(b.keySet());keys.addAll(actual.keySet());for(Integer k:keys){assertNotNull(k);assertTrue(k>=0);Double coefficient=actual.getOrDefault(k,0.0);assertNotNull(coefficient);assertTrue(Double.isFinite(coefficient));BigDecimal expected=new BigDecimal(a.getOrDefault(k,0.0)).add(new BigDecimal(b.getOrDefault(k,0.0)));BigDecimal error=new BigDecimal(coefficient).subtract(expected).abs();BigDecimal tolerance=new BigDecimal("1e-9").add(new BigDecimal("1e-12").multiply(expected.abs()));assertTrue(error.compareTo(tolerance)<=0,"coefficient degree="+k+" expected="+expected+" actual="+coefficient);}HashMap<Integer,Double>copy=new HashMap<>(actual);a.put(999,123.0);b.put(998,456.0);assertEquals(copy,actual);} @Test void emptyCancellationAndExtremeFinite(){check(new HashMap<>(),new HashMap<>());check(new HashMap<>(Map.of(0,1.0,2,3.0)),new HashMap<>(Map.of(1,2.0,2,-3.0)));check(new HashMap<>(Map.of(100,Double.MAX_VALUE,1,1e-300)),new HashMap<>(Map.of(100,-Double.MAX_VALUE,3,2.0)));check(new HashMap<>(Map.of(0,-5.5)),new HashMap<>(Map.of(0,1.25)));}}
